package io.github.jesterportfolio.hearth.survival;
import java.util.*;
import java.nio.file.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
final class SurvivalStorageTest {
 @TempDir Path root;
 static SurvivalSettings settings(boolean create){var defs=new EnumMap<SurvivalWorld,SurvivalSettings.Definition>(SurvivalWorld.class);for(var role:SurvivalWorld.base())defs.put(role,new SurvivalSettings.Definition("test:"+role.id(),role==SurvivalWorld.NETHER?"NETHER":"NORMAL","NORMAL",null));return new SurvivalSettings(UUID.fromString("00000000-0000-0000-0000-000000000001"),create,defs);}
 static Map<SurvivalWorld,WorldRegistry.Entry> entries(){var rows=new EnumMap<SurvivalWorld,WorldRegistry.Entry>(SurvivalWorld.class);for(var role:SurvivalWorld.base())rows.put(role,new WorldRegistry.Entry("test:"+role.id(),UUID.randomUUID(),42,"NORMAL",.5,64,.5));return rows;}
 @Test void registry_roundtrip_binds_group_worlds_seed_and_entries_without_overwrite()throws Exception{var file=root.resolve("worlds.properties");var rows=entries();WorldRegistry.publish(file,settings(true),rows);assertEquals(rows,WorldRegistry.read(file,settings(false)));var before=Files.readAllBytes(file);assertThrows(Exception.class,()->WorldRegistry.publish(file,settings(true),entries()));assertArrayEquals(before,Files.readAllBytes(file));}
 @Test void changed_config_group_missing_or_invalid_registry_is_rejected_and_preserved()throws Exception{var file=root.resolve("worlds.properties");WorldRegistry.publish(file,settings(true),entries());var before=Files.readAllBytes(file);var other=new SurvivalSettings(UUID.randomUUID(),false,settings(false).worlds());assertThrows(Exception.class,()->WorldRegistry.read(file,other));assertArrayEquals(before,Files.readAllBytes(file));Files.writeString(file,"format=1\ngroup="+settings(false).group());assertThrows(Exception.class,()->WorldRegistry.read(file,settings(false)));assertThrows(Exception.class,()->WorldRegistry.read(root.resolve("missing"),settings(false)));}
 @Test void registry_symlink_and_nonfinite_entries_are_rejected()throws Exception{var file=root.resolve("worlds.properties");WorldRegistry.publish(file,settings(true),entries());var link=root.resolve("link");Files.createSymbolicLink(link,file);assertThrows(Exception.class,()->WorldRegistry.read(link,settings(false)));assertThrows(IllegalArgumentException.class,()->new WorldRegistry.Entry("test:w",UUID.randomUUID(),0,"NORMAL",Double.NaN,64,0));}
 @Test void native_save_requires_actual_new_file_and_preserves_old_on_noop_or_failure()throws Exception{var directory=Files.createDirectory(root.resolve("playerdata"));var player=UUID.randomUUID();var file=directory.resolve(player+".dat");Files.writeString(file,"original");assertThrows(IllegalStateException.class,()->VanillaPlayerFiles.save(root,player,()->{}));assertEquals("original",Files.readString(file));assertThrows(IllegalStateException.class,()->VanillaPlayerFiles.save(root,player,()->{throw new IllegalStateException();}));assertEquals("original",Files.readString(file));}
 @Test void native_atomic_replacement_is_acknowledged_without_editing_payload()throws Exception{var directory=Files.createDirectory(root.resolve("playerdata"));var player=UUID.randomUUID();var file=directory.resolve(player+".dat");Files.writeString(file,"original");VanillaPlayerFiles.save(root,player,()->{try{var temp=Files.createTempFile(directory,"profile-",".dat");Files.writeString(temp,"new Minecraft payload");Files.move(temp,file,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(Exception e){throw new IllegalStateException(e);}});assertEquals("new Minecraft payload",Files.readString(file));}
 @Test void native_save_symlink_missing_and_oversized_paths_are_not_followed()throws Exception{var directory=Files.createDirectory(root.resolve("playerdata"));var player=UUID.randomUUID();var external=root.resolve("original");Files.writeString(external,"preserve");Files.createSymbolicLink(directory.resolve(player+".dat"),external);assertThrows(IllegalStateException.class,()->VanillaPlayerFiles.save(root,player,()->fail("must not invoke save")));assertEquals("preserve",Files.readString(external));assertThrows(IllegalStateException.class,()->VanillaPlayerFiles.save(root,UUID.randomUUID(),()->{}));}
 @Test void strict_three_roles_keep_environment_and_identity_distinct(){var defs=new EnumMap<>(settings(false).worlds());defs.put(SurvivalWorld.NETHER,new SurvivalSettings.Definition("test:nether","NORMAL","NORMAL",null));assertThrows(IllegalArgumentException.class,()->new SurvivalSettings(UUID.randomUUID(),true,defs));assertThrows(IllegalArgumentException.class,()->new SurvivalSettings.Definition("../world","NORMAL","NORMAL",null));assertThrows(IllegalArgumentException.class,()->new SurvivalSettings.Definition("test:nether","NETHER","FLAT",null));}
}
